#!/usr/bin/env python3
"""Fix publication evidence lineage in the existing evaluator; no collectors or delivery."""
import base64,datetime as dt,fcntl,gzip,hashlib,json,os,pathlib,re,subprocess,tempfile,time

BUNDLE=''
TARGET=pathlib.Path('/opt/umraniye-osint-deneme/scripts/instagram-intelligence-v1.py')
LOCK=pathlib.Path('/var/lib/umraniye-osint-deneme/.instagram-intelligence.lock')
def execute(args,timeout=45):return subprocess.run(args,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=timeout)
def install():
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 bundle=json.loads(gzip.decompress(base64.b64decode(BUNDLE)));data=base64.b64decode(bundle['code'])
 if TARGET.is_symlink() or TARGET.stat().st_nlink!=1:raise RuntimeError('shared_or_linked_target_rejected')
 original=TARGET.read_bytes()
 if original==data:print(json.dumps({'result':'already_installed','siteRestarted':False,'messagesSent':0}));return
 if hashlib.sha256(original).hexdigest()!=bundle['expected']:raise RuntimeError('version_changed_no_install')
 with tempfile.TemporaryDirectory(prefix='instagram-date-check-') as directory:
  stage=pathlib.Path(directory);(stage/'intelligence.py').write_bytes(data)
  (stage/'test_dates.py').write_bytes(base64.b64decode(bundle['tests']))
  test=execute(['python3',str(stage/'test_dates.py')])
  matched=re.search(r'Ran (\d+) tests',test.stderr)
  if test.returncode or not matched:raise RuntimeError('isolated_tests_failed_no_install')
  regression=execute(['python3',str(stage/'intelligence.py'),'--selftest'])
  if regression.returncode:raise RuntimeError('existing_classifier_regression_failed_no_install')
  preview=execute(['python3',str(stage/'intelligence.py'),'--date-audit'])
  if preview.returncode:raise RuntimeError('readonly_evidence_preview_failed_no_install')
  evidence=json.loads(preview.stdout)
  if evidence.get('databaseWrites')!=0 or evidence.get('apiRequests')!=0:raise RuntimeError('invalid_preview_no_install')
  print('Tarih kanıtı eşleştirmesi ve geçmiş gönderim koruması doğrulandı. Kod yedeği alınıyor; site yeniden başlatılmayacak.',flush=True)
  with LOCK.open('a+') as lock:
   deadline=time.monotonic()+90
   while True:
    try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);break
    except BlockingIOError:
     if time.monotonic()>deadline:raise RuntimeError('evaluator_busy_no_install')
     time.sleep(1)
   if TARGET.read_bytes()!=original:raise RuntimeError('version_changed_during_wait')
   stat=TARGET.stat();backup=pathlib.Path('/var/lib/umraniye-osint-deneme/backups')/('instagram-date-lineage-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
   backup.mkdir(mode=0o700,parents=True);(backup/'original.py').write_bytes(original);os.chmod(backup/'original.py',0o600)
   rollback='''#!/usr/bin/env python3
import fcntl,os,pathlib
target=pathlib.Path(__TARGET__)
with open(__LOCK__,'a+') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 original=pathlib.Path(__file__).resolve().with_name('original.py').read_bytes()
 st=target.stat();temp=target.with_name(target.name+'.rollback-tmp');temp.write_bytes(original)
 os.chmod(temp,st.st_mode & 0o777);os.chown(temp,st.st_uid,st.st_gid);os.replace(temp,target)
print('Tarih değerlendirme kodu geri alındı; kayıtlar, servisler ve Telegram değiştirilmedi.')
'''.replace('__TARGET__',repr(str(TARGET))).replace('__LOCK__',repr(str(LOCK)))
   (backup/'geri-al.py').write_text(rollback,encoding='utf-8');os.chmod(backup/'geri-al.py',0o700)
   temp=TARGET.with_name(TARGET.name+'.date-tmp')
   try:
    with temp.open('wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
    os.chmod(temp,stat.st_mode & 0o777);os.chown(temp,stat.st_uid,stat.st_gid);os.replace(temp,TARGET)
   finally:temp.unlink(missing_ok=True)
   report={'result':'instagram_exact_publication_evidence_installed','at':dt.datetime.now(dt.timezone.utc).isoformat(),
    'changedFiles':[str(TARGET)],'isolatedTestsPassed':int(matched[1]),'existingClassifierSelftestPassed':True,
    'sourceDatesGuessed':False,'firstDiscoveryChanged':False,'reviewFileRewritten':False,
    'historicalReplay':False,'apiRequests':0,'collectorsStarted':False,'databaseWritesByInstaller':0,
    'servicesRestarted':False,'telegramChanged':False,'messagesSent':0,'evidencePreview':evidence,
    'normalEvaluationPending':True,'newLivePostVerified':False,'backup':str(backup),
    'rollback':'sudo python3 '+str(backup/'geri-al.py')}
   (backup/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));os.chmod(backup/'report.json',0o600)
   print(json.dumps(report,ensure_ascii=False,indent=2))

if __name__=='__main__':
 try:install()
 except Exception as error:print('KURULAMADI: '+str(error)[:250]);raise SystemExit(1)
